import { DatePipe } from '@angular/common';
import { Component, OnInit } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { AlertService } from 'src/app/services/alert.service';
import { UserService } from 'src/app/services/emis/user.service';
import { UserSessionService } from 'src/app/services/usersession.service';

@Component({
  selector: 'app-saveddata',
  templateUrl: './saveddata.page.html',
  styleUrls: ['./saveddata.page.scss'],
})
export class SaveddataPage implements OnInit {
  pipe = new DatePipe('en-US');
  routeData: any;
  page: any;
  todayDate: string;
  todayDateFormat: string;
  sessionUserName: number;
  trainerData: any[];
  trainingList: any[];
  noData: boolean;
  traineeData: any[];

  constructor(private router: Router, private alertService: AlertService, private route: ActivatedRoute,
    private usersessionService: UserSessionService, private userService: UserService) { }

  ngOnInit() {
    
  }

  ionViewDidEnter() {
    debugger
    this.todayDate = this.pipe.transform(new Date(), 'dd-MM-yyyy');
    this.todayDateFormat = this.pipe.transform(new Date(), 'yyyy-MM-dd');

    this.sessionUserName = this.usersessionService.emis_username();
    this.routeData = this.route.snapshot;
    this.page = this.routeData.queryParams.page;

    this.userService.getTeacherTrainingList().subscribe(res => {
      if (res.dataStatus) {
        this.trainingList = res.result;
        if(this.page == 1) {
          this.getTrainerData();
        } else {
          this.getTrianeeData();
        }
      }
    });
    
    
  }

  getTrainerData(){
    this.userService.getTrainnerData(this.sessionUserName, this.todayDateFormat).subscribe(res => {
      if (res.dataStatus) {
        this.noData = false;
        this.trainerData= res.result;
        this.trainerData.forEach(a => {
          let assignBookList = this.trainingList.filter(tt => tt.IndexId == a.TrainiType);
          if(assignBookList.length > 0) {
            a.training = assignBookList[0].TranNme;
          } else {
            a.training = '';
          }
         
        });
        console.log(this.trainerData)
      } else {
        this.noData = true;
      }
    });
  }

  getTrianeeData(){
    this.userService.getTrainingData(this.sessionUserName).subscribe(res => {
      if (res.dataStatus) {
        this.noData = false;
        this.traineeData= res.result.filter(tt => tt.TrainiDate == this.todayDateFormat);;
        console.log(res)
      } else {
        this.noData = true;
      }
    });
  }

  navigateBack(){
    this.router.navigate(['/tabs/training-attendance']);
  }

}
